def get_pell_number(n):

    if n == 0:

        return 0

    elif n == 1:

        return 1



    pell_prev_prev = 0

    pell_prev = 1



    for _ in range(2, n + 1):

        pell_current = 2 * pell_prev + pell_prev_prev

        pell_prev_prev = pell_prev

        pell_prev = pell_current



    return pell_current

def sum_of_multiples(lower, upper):

    total = 0

