def is_valid_password(password):

    letters = 0

    numbers = 0

    for character in password:

        if character.isalpha() == True:

            letters += 1

        elif character.isdigit() == True:

            numbers += 1

    if letters >= 5 and numbers >= 4:

        if len(password) >= 10:

            if "123" not in password and "abc" not in password:

                return True

            else:

                return False

        else:

            return False

    else:

        return False

