        return "Capricorn"

    elif (month == "January" and day >= 20) or (day <= 18 and month == "February"):

        return "Aquarius"

    elif (month == "February" and day >= 19) or (day <= 20 and month == "March"):

        return "Pisces"

    elif (month == "March" and day >= 21) or (day <= 19 and month == "April"):

        return "Aries"

    elif (month == "April" and day >= 20) or (day <= 20 and month == "May"):

        return "Taurus"

    elif (month == "May" and day >= 21) or (day <= 20 and month == "June"):

        return "Gemini"

    elif (month == "June" and day >= 22) or (day <= 22 and month == "July"):

        return "Cancer"

    elif (month == "July" and day >= 23) or (day <= 22 and month == "August"):

        return "Leo"

    elif (month == "August" and day >= 23) or (day <= 22 and month == "September"):

        return "Virgo"

    elif (month == "September" and day >= 23) or (day <= 22 and month == "October"):

        return "Libra"

    elif (month == "October" and day >= 23) or (day <= 21 and month == "November"):

        return "Scorpio"

    elif (month == "Sagittarius" and day >= 22) or (day <= 21 and month == "December"):

        return "Sagittarius"

    else:

       raise AssertionError("Unexpected value from day and month")





