def get_wave_type(wavelength):

    if wavelength < 1e-11:

        wave_type = "Gamma"

    elif 1e-11 <= wavelength < 1e-8:

        wave_type = "X-Ray"

    elif 1e-8 <= wavelength < 3.8e-7:

        wave_type = "Ultraviolet"

    elif 3.8e-7 <= wavelength < 7.5e-7:

        wave_type = "Visible"

    elif 7.5e-7 <= wavelength < 1e-3:

        wave_type = "Infrared"

    elif 1e-3 <= wavelength < 1:

        wave_type = "Microwave"

    else:

        wave_type = "Radio"



    if wave_type == "X-Ray":

        return "an " + wave_type + " wave"

    elif wave_type == "Infrared":

        return "an " + wave_type + " wave"

    else:

        return "a " + wave_type + " wave"

def get_wave_type(wavelength):

    if wavelength < 1e-11:

        return f"an X-Ray wave"

    elif 1e-11 <= wavelength < 1e-8:

        return f"an X-Ray wave"

