def get_duplicates_count(numbers_list):

    counts = []

    for num in numbers_list:

        count = numbers_list.count(num)

        if (num, count) not in counts and count!=1:

            counts.append((num, count))

    return sorted(counts)

def get_duplicates_count(numbers_list):

    reappear = []

    count = []

    duplicates = []

    numbers_list.sort()



    for element in numbers_list:

        if element in reappear:

            index = reappear.index(element)

            count[index] += 1



        else:

            reappear.append(element)

            count.append(1)



    for j in range(len(reappear)):

        if count[j] > 1:

            temp_tuple = (reappear[j], count[j])

            duplicates.append(temp_tuple)



    return duplicates

