        return 2 * get_pell_number(n-1) + get_pell_number(n-2)

def get_pell_number(n):

    if n == 0:

        return 0

    elif n == 1:

        return 1





    pell_minus_two = 0  # P_0

    pell_minus_one = 1  # P_1

    current_pell = None





    for i in range(2, n + 1):

        current_pell = 2 * pell_minus_one + pell_minus_two

        # Update the previous two Pell numbers

        pell_minus_two, pell_minus_one = pell_minus_one, current_pell



    return current_pell

