def check_password(password):

    password = password.strip()



    if len(password) < 10:

        return False



    if "123" in password or "abc" in password:

        return False



    if sum(c.isdigit() for c in password) < 4:

        return False



    if sum(c.isalpha() for c in password) < 5:

        return False



    return True

